    objective.SetCoefficient(x4, 25)

    # Add constraints
    solver.Add(x1 + x2 <= 12)
    solver.Add(x3 + x4 <= 16)
    solver.Add(x1 + x3 >= 8)
    solver.Add(x2 + x4 >= 10)

    # Solve the problem
    status = solver.Solve()

    # Extract the objective value
    total_fatigue = 10 * x1.solution_value() + 15 * x2.solution_value() + 20 * x3.solution_value() + 25 * x4.solution_value()

