    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    x = solver.IntVar(0, 70, 'x')  # Ships on Route X
    y = solver.IntVar(0, 50, 'y')  # Ships on Route Y

    # Objective: minimize total cost
    total_cost = 10 * x + 20 * y
    solver.Minimize(total_cost)

    # Constraints
    solver.Add(x + y <= 100)  # Total ships constraint
    solver.Add(2 * x + y >= 60)  # Combined capacity constraint
    solver.Add(x - y <= 30)  # Upper bound on x - y
    solver.Add(y - x <= 30)  # Lower bound on x - y

    # Solve the problem
    status = solver.Solve()

    # Map status
    if status == pywraplp.Solver.OPTIMAL:
        status_name = 'OPTIMAL'
    elif status == pywraplp.Solver.FEASIBLE:
        status_name = 'FEASIBLE'
    else:
        status_name = 'NOT_SOLVED'

    # Calculate objective value
    objective_value = total_cost.solution_value()

    # Print result
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

