import sys
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')
    if not solver:
        print("Solver not found.")
        return

    # Define decision variables
    x1 = solver.IntVar(0, sys.maxsize, 'x1')
    x2 = solver.IntVar(0, sys.maxsize, 'x2')
    x3 = solver.IntVar(0, sys.maxsize, 'x3')
    x4 = solver.IntVar(0, sys.maxsize, 'x4')

    # Objective function: minimize total cost
    cost = 50 * x1 + 30 * x2 + 20 * x3 + 10 * x4
    solver.Minimize(cost)

    # Constraint 1: x1 + x2 <= 1000
    solver.Add(x1 + x2 <= 1000)

    # Constraint 2: 2*x3 + 3*x4 >= 500
    solver.Add(2 * x3 + 3 * x4 >= 500)

    # Constraint 3: |x1 - x4| <= 200
    solver.Add(x1 - x4 <= 200)
    solver.Add(x4 - x1 <= 200)

    # Constraint 4: 0.5*x3 >= x2 => x3 >= 2*x2
    solver.Add(x3 >= 2 * x2)

    # Solve the problem
    status = solver.Solve()

    # Map status
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = cost.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": total_cost
        }
    else:
        result = {
            "status": "NOT_SOLVED",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

