import math
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('GLOP')

    # Define decision variables
    x = solver.NumVar(0, 1.5, 'x')  # Width of the rectangular portion
    y = solver.NumVar(0, 2, 'y')   # Height of the rectangular portion

    # Calculate radius of the semicircle
    r = x / 2

    # Objective function: maximize light transmitted
    # Light through clear glass: x * y
    # Light through colored glass: 0.5 * π * r^2
    objective = x * y + 0.5 * math.pi * (r ** 2)
    solver.Maximize(objective)

    # Constraint: total height (y + 2r) <= 2
    solver.Add(y + 2 * r <= 2)

    # Solve the problem
    status = solver.Solve()

    # Check the status and extract the result
    if status == pywraplp.Solver.OPTIMAL:
        light_transmitted = objective.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": light_transmitted
        }
    else:
        result = {
            "status": "NOT_SOLVED",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
