from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    x = solver.IntVar(0, 1000, 'x')
    y = solver.IntVar(0, 1000, 'y')
    z = solver.IntVar(0, 1000, 'z')

    # Objective function: minimize total operational cost
    cost = 2 * x + 3 * y + 4 * z
    solver.Minimize(cost)

    # Constraint 1: Total ships cannot exceed 1000
    solver.Add(x + y + z <= 1000)

    # Constraint 2: 2x + y >= 500
    solver.Add(2 * x + y >= 500)

    # Constraint 3: |y - z| <= 300 (linearized using two constraints)
    solver.Add(y - z <= 300)
    solver.Add(z - y <= 300)

    # Solve the problem
    status = solver.Solve()

    # Map status to corresponding name
    if status == pywraplp.Solver.OPTIMAL:
        status_name = 'OPTIMAL'
    elif status == pywraplp.Solver.FEASIBLE:
        status_name = 'FEASIBLE'
    else:
        status_name = 'NOT_SOLVED'

    # Calculate the objective value
    objective_value = cost.solution_value()

    # Print the result
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
