import json
from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('GLOP')

    # Define regions
    regions = [1, 2, 3, 4, 5]

    # Cost matrix
    cost = {
        (1, 3): 13, (1, 4): 11, (1, 5): 28,
        (2, 3): 18, (2, 4): 8, (2, 5): 46,
        (3, 4): 9, (3, 5): 27,
        (4, 5): 20
    }

    # Supply and demand
    supply = {1: 120, 2: 330, 3: 400, 4: 400, 5: 600}
    demand = {1: 150, 2: 200, 3: 600, 4: 200, 5: 400}

    # Create variables
    x = {}
    for i in regions:
        for j in regions:
            if i != j:
                x[(i, j)] = solver.NumVar(0, solver.infinity(), f'x_{i}_{j}')

    # Objective function: minimize total cost
    objective = solver.Objective()
    for (i, j), c in cost.items():
        objective.SetCoefficient(x[(i, j)], c)
    objective.SetMinimization()

    # Balance constraints for each region
    for region in regions:
        # Net flow for the region
        net_flow = solver.Sum([x[(i, region)] for i in regions if i != region]) - solver.Sum([x[(region, j)] for j in regions if j != region])
        # Supply minus demand for the region
        balance = supply[region] - demand[region]
        solver.Add(net_flow == balance)

    # Solve the problem
    status = solver.Solve()

    # Calculate total cost
    total_cost = 0.0
    for (i, j), c in cost.items():
        total_cost += x[(i, j)].solution_value() * c

    # Map status
    status_map = {
        pywraplp.Solver.OPTIMAL: 'OPTIMAL',
        pywraplp.Solver.NOT_SOLVED: 'NOT_SOLVED',
        pywraplp.Solver.ABNORMAL: 'ABNORMAL',
        pywraplp.Solver.NOT_SOLVED: 'NOT_SOLVED',
        pywraplp.Solver.FEASIBLE: 'FEASIBLE',
        pywraplp.Solver.INFEASIBLE: 'INFEASIBLE',
        pywraplp.Solver.UNBOUNDED: 'UNBOUNDED'
    }
    status_name = status_map.get(status, 'UNKNOWN')

    # Print result
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

