from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('GLOP')

    # Define decision variables
    x = solver.NumVar(0, solver.infinity(), 'x')  # Days to operate old farm
    y = solver.NumVar(0, solver.infinity(), 'y')  # Days to operate new farm

    # Define the objective function: minimize cost
    cost = 300 * x + 200 * y
    solver.Minimize(cost)

    # Add constraints for berry requirements
    solver.Add(2 * x + 4 * y >= 10)  # Raspberries
    solver.Add(2 * x + 1 * y >= 9)  # Blueberries
    solver.Add(4 * x + 2 * y >= 15)  # Strawberries

    # Solve the problem
    status = solver.Solve()

    # Check the status and extract the result
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = cost.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": total_cost
        }
    else:
        result = {
            "status": "NOT_SOLVED",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
