    solver = pywraplp.Solver.CreateSolver('CBC_MIXED_INTEGER_PROGRAMMING')

    # Define decision variables
    x = solver.IntVar(0, solver.infinity(), 'x')
    y = solver.IntVar(0, solver.infinity(), 'y')
    z = solver.IntVar(0, solver.infinity(), 'z')

    # Objective function: minimize total cost (2x + 3y + z)
    total_cost = 2 * x + 3 * y + z
    solver.Minimize(total_cost)

    # Constraint 1: Total resources cannot exceed 1000
    solver.Add(x + y + z <= 1000)

    # Constraint 2: Combined resources for Y and Z must be at least 800
    solver.Add(y + z >= 800)

    # Constraint 3: Resource difference between X and Z must not exceed 200
    solver.Add(x - z <= 200)
    solver.Add(z - x <= 200)

    # Solve the problem
    status = solver.Solve()

    # Map status to corresponding name
    status_name = {
        pywraplp.Solver.OPTIMAL: 'OPTIMAL',
        pywraplp.Solver.FEASIBLE: 'FEASIBLE',
        pywraplp.Solver.INFEASIBLE: 'INFEASIBLE',
        pywraplp.Solver.UNBOUNDED: 'UNBOUNDED',
        pywraplp.Solver.NOT_SOLVED: 'NOT_SOLVED',
        pywraplp.Solver.ABNORMAL: 'ABNORMAL'
    }.get(status, 'NOT_SOLVED')

    # Calculate the objective value
    objective_value = total_cost.solution_value()

    # Print the result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

