def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('GLOP')

    # Define nodes
    nodes = [1, 2, 3, 4]

    # Define edges and their capacities
    edges = [
        (1, 2, 8),
        (1, 3, 7),
        (2, 3, 2),
        (2, 4, 4),
        (3, 4, 12)
    ]

    # Create variables for each edge
    flow = {}
    for i, j, _ in edges:
        flow[(i, j)] = solver.NumVar(0, solver.infinity(), f'flow_{i}_{j}')

    # Objective: maximize total flow from node 1 to node 4
    total_flow = flow[(1, 2)] + flow[(1, 3)]
    solver.Maximize(total_flow)

    # Flow conservation constraints
    # Node 2: inflow from 1 - outflow to 3 and 4 = 0
    solver.Add(flow[(1, 2)] - flow[(2, 3)] - flow[(2, 4)] == 0)
    # Node 3: inflow from 1 and 2 - outflow to 4 = 0
    solver.Add(flow[(1, 3)] + flow[(2, 3)] - flow[(3, 4)] == 0)

    # Capacity constraints
    solver.Add(flow[(1, 2)] <= 8)
    solver.Add(flow[(1, 3)] <= 7)
    solver.Add(flow[(2, 3)] <= 2)
    solver.Add(flow[(2, 4)] <= 4)
    solver.Add(flow[(3, 4)] <= 12)

    # Solve the problem
    status = solver.Solve()

    # Check the status and extract the result
    if status == pywraplp.Solver.OPTIMAL:
        max_flow_value = total_flow.solution_value()
        result = {
            "status": "OPTIMAL",
            "objective_value": max_flow_value
