from ortools.linear_solver import pywraplp

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('GLOP')

    # Define decision variables
    x = solver.NumVar(0, solver.infinity(), 'x')
    y = solver.NumVar(0, solver.infinity(), 'y')

    # Define the objective function
    # Revenue: 20x + 30y
    # Machine time cost: (13/6)x + (19/6)y
    # Craftsman time cost: (20/30)x + (29/30)y
    profit = (20 * x) + (30 * y) - ((13/6) * x) - ((19/6) * y) - ((20/30) * x) - ((29/30) * y)
    solver.Maximize(profit)

    # Add constraints
    solver.Add(13 * x + 19 * y <= 2400)  # Machine time constraint
    solver.Add(20 * x + 29 * y <= 2100)  # Craftsman time constraint
    solver.Add(x >= 10)  # Contractual requirement

    # Solve the problem
    status = solver.Solve()

    # Calculate the objective value
    objective_value = profit.solution_value()

    # Map status
    if status == pywraplp.Solver.OPTIMAL:
        status_name = 'OPTIMAL'
    else:
        status_name = 'NOT_SOLVED'

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

